def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 4:
                rich_opp += 1
            prev = opp.get('previous_trace') or {}
            bid = prev.get('bid')
            err = prev.get('error')
            if bid is not None and not err:
                try:
                    prev_bids.append(float(bid))
                except Exception:
                    pass

    if budget <= 0:
        return 0

    if not alive_opponents:
        return min(budget, 21)

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    my_urgent = 0
    if hp <= 2 or no_water_days >= 2:
        my_urgent = 1
    elif hp <= 4 or no_water_days >= 1:
        my_urgent = 0.5

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if my_urgent >= 1:
        target = max(58.0, highest_prev + 2.0)
        if supply <= 18:
            target = max(target, 64.0)
        return min(budget, round(target, 2))

    base = 24.0 + 18.0 * scarcity
    base += 4.0 * urgent_opp
    base += 2.0 * rich_opp

    if prev_bids:
        if supply <= 18:
            target = max(base, highest_prev + 1.5)
        else:
            target = max(base, avg_prev + 1.0)
    else:
        target = base

    if hp >= 8 and no_water_days == 0 and supply >= 22:
        target *= 0.78
    elif hp >= 6 and supply >= 20:
        target *= 0.9

    if day >= 8:
        target += 4.0
    if budget < DAILY_SALARY * 2:
        target = min(target, budget * 0.55)

    target = max(8.0, min(target, DAILY_SALARY * 0.95, budget))
    return round(target, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', MIN_SUPPLY))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents, bid just enough to satisfy requirement
    if not alive_opps:
        bid = WATER_REQ
        return float(min(budget, bid))

    # Read yesterday bids from previous_trace (immediate reaction)
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Survival logic
    if hp <= 2 or no_water_days >= 2:
        # Go high but cap by budget
        return float(min(budget, DAILY_SALARY * 0.95))

    # If opponents were bidding heavily yesterday, slightly increase to contest
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If they signaled high pressure, match/beat moderately
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = min(budget, DAILY_SALARY * 0.65)
        else:
            # Otherwise, bid near requirement plus a small premium
            # Premium scales with how tight the supply is
            tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
            premium = 2.0 + 6.0 * float(tightness)
            target = WATER_REQ + premium
            target = min(target, DAILY_SALARY * 0.75)
        return float(max(0.0, min(budget, target)))

    # Default when no previous_trace data: bid moderately based on supply tightness
    tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    base = WATER_REQ + (3.0 + 6.0 * float(tightness))
    # Keep it conservative to avoid overpaying
    target = min(base, DAILY_SALARY * 0.6)
    return float(max(0.0, min(budget, target)))

